import React from "react";
import AppTheme from "@/components/Settings/theme";
import { Button, Card, Message, Tooltip } from "@arco-design/web-react";
import app from "@/store/app";
import useLocale from "@/utils/useLocale";
import { IconMoonFill, IconSunFill } from "@arco-design/web-react/icon";
import { useObserver } from "mobx-react-lite";
import theme from "@/store/theme";
import { AsyncButton } from "@/components/custom";

const Index = () => {
  const t = useLocale();

  return useObserver(() => {

    return (
      <Card title="主题色设置"
        extra={
          <AsyncButton type="primary"
            onClick={() => {
              app.assignExtraInfo({
                themes: theme.getAppTheme(),
              })
              return app.savaExtraInfo().then(() => {
                Message.success("保存成功");
              })
            }}
          >
            保存
          </AsyncButton>
        }
      >
        <AppTheme />
      </Card>
    )

  })
}


export default Index;